package com.andye.warmod.phalanx;
import com.andye.warmod.block.PhalanxStructure;import com.andye.warmod.block.entity.PhalanxBlockEntity;import java.util.*;import net.fabricmc.fabric.api.event.lifecycle.v1.*;import net.minecraft.server.level.ServerLevel;
public final class PhalanxManager{private static final Map<ServerLevel,Map<UUID,PhalanxBlockEntity>> ACTIVE=new WeakHashMap<>();private static boolean registered;private PhalanxManager(){}public static void registerLifecycle(){if(registered)return;ServerLifecycleEvents.SERVER_STOPPED.register(s->{ACTIVE.clear();PhalanxChunkTicketManager.clear();});registered=true;}public static synchronized boolean canPlace(ServerLevel level){return ACTIVE.getOrDefault(level,Map.of()).size()<PhalanxConstants.MAX_TURRETS_PER_LEVEL;}public static synchronized PhalanxRegistrationResult register(ServerLevel level,PhalanxBlockEntity turret){if(!PhalanxStructure.complete(level,turret.getBlockPos()))return PhalanxRegistrationResult.rejected(PhalanxRegistrationFailure.INCOMPLETE_STRUCTURE);var map=ACTIVE.computeIfAbsent(level,x->new LinkedHashMap<>());var existing=map.get(turret.turretId());if(existing!=null)return existing==turret?PhalanxRegistrationResult.success():PhalanxRegistrationResult.rejected(PhalanxRegistrationFailure.DUPLICATE_UUID);if(!canPlace(level))return PhalanxRegistrationResult.rejected(PhalanxRegistrationFailure.LIMIT_REACHED);for(var registered:map.values())if(registered.getBlockPos().equals(turret.getBlockPos()))return PhalanxRegistrationResult.rejected(PhalanxRegistrationFailure.POSITION_OCCUPIED);if(!PhalanxChunkTicketManager.register(level,turret.turretId(),turret.getBlockPos()))return PhalanxRegistrationResult.rejected(PhalanxRegistrationFailure.MANAGER_REJECTED);map.put(turret.turretId(),turret);return PhalanxRegistrationResult.success();}public static synchronized void unregister(ServerLevel level,PhalanxBlockEntity turret){PhalanxChunkTicketManager.unregister(level,turret.turretId());var map=ACTIVE.get(level);if(map!=null){map.remove(turret.turretId());if(map.isEmpty())ACTIVE.remove(level);}}}